mapper.select:
		SELECT COUNT(*)
		FROM product p



				AND p.name LIKE '%' || #{keyword} || '%'




				AND p.category_id IN (
	        			SELECT category_id
	        			FROM category
	        			START WITH category_id = #{searchCategoryId}
	        			CONNECT BY PRIOR category_id = parent_id
    				)



				AND p.use_yn = #{useYn}



				AND p.same_day_delivery_yn = #{sameDayDeliveryYn}

mapper.update:
UPDATE product_option
SET
    color = #{dto.color},
    option_size = #{dto.optionSize},
    stock = #{dto.stock},
    use_yn = #{dto.useYn}
WHERE product_no = #{productNo} 
  AND product_option_no = #{productOptionNo}

mapper.delete:
DELETE FROM product_option
WHERE product_no = #{productNo}
  AND product_option_no = #{productOptionNo}
